INSERT INTO `culture_timeline` VALUES ('tl-1',1,'1970-an','Sanggar-sanggar Topeng Malangan di Kabupaten Malang mencapai masa kejayaan karena tingginya permintaan pentas dari desa ke desa.'),('tl-2',2,'1976-1985','Bupati Malang Eddy Slamet mendorong pelestarian teater Wayang Topeng Malang, mendukung berdirinya Sanggar Asmorobangun di Kedungmonggo, Pakisaji.'),('tl-3',3,'Era Mbah Karimun','Mbah Karimun, sesepuh & maestro topeng Malangan, menerima penghargaan dari Presiden Soeharto atas jasanya melestarikan kesenian tradisional.'),('tl-4',4,'2010-sekarang','Sanggar diteruskan oleh cucu Mbah Karimun, Tri Handoyo, dan tetap rutin menggelar pentas Gebyak Senen Legian setiap bulan menurut kalender Jawa.');
