INSERT INTO `faqs` VALUES ('faq-1',1,'Apakah kelas tari berbayar?','Untuk kelas tari wisata dikenakan biaya Rp 15.000 setiap pertemuan. Sedangkan kelas karawitan masih gratis untuk saat ini.'),('faq-2',2,'Apakah harus punya pengalaman sebelumnya untuk ikut kelas?','Tidak. Setiap calon peserta akan mengikuti progres kelas yang sudah berjalan sesuai kelompok yang dipilih.'),('faq-3',3,'Bagaimana saya tahu pendaftaran saya berhasil?','Konfirmasi pendaftaran berhasil akan dikirimkan melalui akun email yang dimasukkan ketika melakukan pendaftaran.');
